class NodePattern:
    def __init__(self, type: Optional[int] = None, content: Optional[Iterable[Text]] = None, name: Optional[Text] = None) -> None:
        """
        Initializes a NodePattern object.

        Args:
            type (Optional[int]): The type of the node, must be >= 256 if provided. If None, it matches any single node (leaf or not), except when content is not None, in which case it only matches non-leaf nodes that also match the content pattern.
            content (Optional[Iterable[Text]]): A sequence of patterns that must match the node's children exactly. Must be a sequence of BasePattern objects and cannot be a string. If provided, type must not be None.
            name (Optional[Text]): The key under which the matching node will be stored in the results dictionary.
        """
        if type is not None:
            assert type >= 256, type
        if content is not None:
            assert not isinstance(content, str), repr(content)
            newcontent = list(content)
            for i, item in enumerate(newcontent):
                assert isinstance(item, BasePattern), (i, item)
                if isinstance(item, WildcardPattern):
                    self.wildcards = True
        self.type = type
        self.content = newcontent
        self.name = name

    def _submatch(self, node, results=None) -> bool:
        """
        Match the pattern's content to the node's children.

        This assumes the node type matches and self.content is not None.

        Returns True if it matches, False if not.

        If results is not None, it must be a dict which will be updated with the nodes matching named subpatterns.
        """
        if self.wildcards:
            for c, r in generate_matches(self.content, node.children):
                if c == len(node.children):
                    if results is not None:
                        results.update(r)
                    return True
            return False
        if len(self.content) != len(node.children):
            return False
        for subpattern, child in zip(self.content, node.children):
            if not subpattern.match(child, results):
                return False
        return True
